CREATE TABLE tb_categoria (id BIGINT NOT NULL AUTO_INCREMENT, nome VARCHAR(100) NOT NULL, descricao VARCHAR(250), PRIMARY KEY(id), UNIQUE KEY uk_categoria_nome(nome)); CREATE TABLE tb_book (id BIGINT NOT NULL AUTO_INCREMENT, author VARCHAR(180) NOT NULL, title VARCHAR(250) NOT NULL, launch_date DATE NOT NULL, price DOUBLE NOT NULL, categoria_id BIGINT NOT NULL, PRIMARY KEY(id), CONSTRAINT fk_book_categoria FOREIGN KEY(categoria_id) REFERENCES tb_categoria(id));